  private func exportFile(_ arguments: Any?, result: @escaping FlutterResult) {
    guard let args = arguments as? [String: Any], let sourcePath = args["path"] as? String, !sourcePath.isEmpty else { result(FlutterError(code: "invalid_arguments", message: "exportFile requires a non-empty path.", details: nil)); return }; let source = URL(fileURLWithPath: sourcePath).standardizedFileURL
    do { let sourceValues = try source.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey]); guard sourceValues.isRegularFile == true else { result(FlutterError(code: "missing_file", message: "The export source is not a regular file.", details: nil)); return }; let sourceSize = Int64(sourceValues.fileSize ?? 0); guard sourceSize >= 0 && sourceSize <= Self.maxExportBytes else { result(FlutterError(code: "export_too_large", message: "The export exceeds the 64 MB portable-backup limit.", details: ["maxBytes": Self.maxExportBytes, "size": sourceSize])); return }; guard let presenter = activePresenter(), NativePresentationResolver.isPresentationReady(presenter) else { result(FlutterError(code: "no_presenter", message: "No active iOS scene is available.", details: nil)); return }; cleanupOrphanedExports(); let root = exportRootDirectory(); try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true); try protectAndExcludeFromBackup(root); let session = root.appendingPathComponent(UUID().uuidString.lowercased(), isDirectory: true); try FileManager.default.createDirectory(at: session, withIntermediateDirectories: true); try protectAndExcludeFromBackup(session); let preferredName = sanitizedFilename(args["filename"] as? String) ?? sanitizedFilename(source.lastPathComponent) ?? "quran-backup.dat", staged = session.appendingPathComponent(preferredName, isDirectory: false); do { try FileManager.default.copyItem(at: source, to: staged); try protectAndExcludeFromBackup(staged); let attributes = try FileManager.default.attributesOfItem(atPath: staged.path), copiedSize = (attributes[.size] as? NSNumber)?.int64Value ?? -1; guard copiedSize >= 0 && copiedSize <= Self.maxExportBytes else { throw DocumentHandoffError.exportTooLargeAfterCopy(size: copiedSize) } } catch { try? FileManager.default.removeItem(at: session); throw error }; temporaryExportURL = staged; pendingResult = result; let picker = UIDocumentPickerViewController(forExporting: [staged], asC