  }
  private func importFile(result: @escaping FlutterResult) { guard let presenter = activePresenter(), NativePresentationResolver.isPresentationReady(presenter) else { result(FlutterError(code: "no_presenter", message: "No active iOS scene is available.", details: nil)); return }; pendingResult = result; let picker = UIDocumentPickerViewController(forOpeningContentTypes: [.data], asCopy: true); picker.allowsMultipleSelection = false; picker.delegate = self; picker.modalPresentationStyle = .formSheet; presentedDocumentPicker = picker; presenter.present(picker, animated: true) }
  private func deleteImportedFile(_ arguments: Any?, result: @escaping FlutterResult) { guard let args = arguments as? [String: Any], let rawPath = args["path"] as? String, !rawPath.isEmpty else { result(FlutterError(code: "invalid_arguments", message: "deleteImportedFile requires a path.", details: nil)); return }; do { let directory = try importDirectory().standardizedFileURL, target = URL(fileURLWithPath: rawPath).standardizedFileURL; guard target.deletingLastPathComponent() == directory else { result(FlutterError(code: "invalid_import_path", message: "Only files created by the import handoff can be deleted.", details: nil)); return }; if FileManager.default.fileExists(atPath: target.path) { try FileManager.default.removeItem(at: target) }; result(["deleted": true]) } catch { result(FlutterError(code: "import_cleanup_failed", message: error.localizedDescription, details: nil)) } }
