  func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) { guard let picked = urls.first else { finish(["status": "cancelled"]); return }; let scoped = picked.startAccessingSecurityScopedResource(); defer { if scoped { picked.stopAccessingSecurityScopedResource() } }; do { let sourceValues = try picked.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey]); guard sourceValues.isRegularFile == true else { finish(error: FlutterError(code: "import_not_file", message: "The selected item is not a regular file.", details: nil)); return }; let sourceSize = Int64(sourceValues.fileSize ?? 0); guard sourceSize >= 0 && sourceSize <= Self.maxImportBytes else { finish(error: FlutterError(code: "import_too_large", message: "The selected backup exceeds the 64 MB portable-backup limit.", details: ["maxBytes": Self.maxImportBytes, "size": sourceSize])); return }; let inbox = try importDirectory(), destination = uniqueDestination(in: inbox, filename: sanitizedFilename(picked.lastPathComponent) ?? "import.quranbackup"); try FileManager.default.copyItem(at: picked, to: destination); try protectAndExcludeFromBackup(destination); let attributes = try FileManager.default.attributesOfItem(atPath: destination.path), size = (attributes[.size] as? NSNumber)?.int64Value ?? 0; guard size <= Self.maxImportBytes else { try? FileManager.default.removeItem(at: destination); finish(error: FlutterError(code: "import_too_large", message: "The copied backup exceeds the 64 MB portable-backup limit.", details: ["maxBytes": Self.maxImportBytes, "size": size])); return }; finish(["status": "selected", "path": destination.path, "filename": destination.lastPathComponent, "size": size]) } catch { finish(error: FlutterError(code: "import_failed", message: error.localizedDescription, details: nil)) } }
