  private func exportRootDirectory() -> URL { FileManager.default.temporaryDirectory.appendingPathComponent(Self.exportDirectoryName, isDirectory: true) }
  private func cleanupOrphanedExports(now: Date = Date()) { let root = exportRootDirectory(); guard let sessions = try? FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: [.contentModificationDateKey, .isDirectoryKey], options: [.skipsHiddenFiles]) else { return }; let active = temporaryExportURL?.deletingLastPathComponent().standardizedFileURL; for session in sessions { guard session.standardizedFileURL != active, let values = try? session.resourceValues(forKeys: [.contentModificationDateKey, .isDirectoryKey]), values.isDirectory == true, let modified = values.contentModificationDate, now.timeIntervalSince(modified) >= Self.orphanLifetime else { continue }; try? FileManager.default.removeItem(at: session) } }
  private func importDirectory() throws -> URL { let base = try FileManager.default.url(for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil, create: true), directory = base.appendingPathComponent("ImportedUserBackups", isDirectory: true); try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true); try protectAndExcludeFromBackup(directory); return directory }
  private func protectAndExcludeFromBackup(_ url: URL) throws { try FileManager.default.setAttributes([.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication], ofItemAtPath: url.path); var values = URLResourceValues(); values.isExcludedFromBackup = true; var mutable = url; try mutable.setResourceValues(values) }
  private func uniqueDestination(in directory: URL, filename: String) -> URL { let base = URL(fileURLWithPath: filename).deletingPathExtension().lastPathComponent, ext = URL(fileURLWithPath: filename).pathExtension; var candidate = directory.appendingPathComponent(filename), index = 2; while FileManager.default.fileExists(atPath: candidate.path) { candidate = directory.appendingPathComponent(ext.isEmpty ? "\(base)-\(index)" : "\(base)-\(index).\(ext)"); index += 1 }; return candidate }
  private func sanitizedFilename(_ value: String?) -> String? { guard let value else { return nil }; let leaf = URL(fileURLWithPath: value).lastPathComponent.trimmingCharacters(in: .whitespacesAndNewlines); return (!leaf.isEmpty && leaf != "." && leaf != "..") ? leaf : nil }
